/**
* Mark constructor.
*
* @constructor
* @param {Options} options - constructor options
* @param {string} options.type - mark type
* @param {boolean} [options.aria=true] - boolean indicating whether to include ARIA attributes in SVG output
* @param {string} [options.blend] - color blend mode for drawing an item on its current background
* @param {(boolean|Clip)} [options.clip=false] - setting indicating whether to clip marks to a specified shape
* @param {string} [options.cursor] - mouse cursor used over the mark
* @param {string} [options.description] - text description of a mark for ARIA accessibility
* @param {Object} [options.encode] - object containing visual encoding rules for mark properties
* @param {string} [options.fill] - fill color
* @param {number} [options.fillOpacity] - fill opacity from 0 (transparent) to 1 (opaque)
* @param {Object} [options.from] - object describing the data a mark should visualize
* @param {number} [options.height] - height of the mark in pixels
* @param {string} [options.href] - URL to load upon mouse click
* @param {(boolean|Signal)} [options.interactive=true] - boolean indicating whether a mark can serve as an input event source
* @param {(string|Object)} [options.key] - data field to use as a unique key for data binding
* @param {string} [options.name] - unique name
* @param {number} [options.opacity] - mark opacity from 0 (transparent) to 1 (opaque)
* @param {string} [options.role] - metadata string indicating the role of a mark
* @param {Compare} [options.sort] - comparator for sorting mark items
* @param {string} [options.stroke] - stroke color
* @param {string} [options.strokeCap] - stroke cap for line ending style
* @param {NumericArray} [options.strokeDash] - array of [stroke, space] lengths for creating dashed or dotted lines
* @param {number} [options.strokeDashOffset] - pixel offset at which to start the stroke dash array
* @param {string} [options.strokeJoin] - stroke line join method
* @param {number} [options.strokeMiterLimit] - miter limit at which to bevel a line join
* @param {number} [options.strokeOpacity] - stroke opacity from 0 (transparent) to 1 (opaque)
* @param {number} [options.strokeWidth] - stroke width in pixels
* @param {(string|Array<string>)} [options.style] - custom styles to apply to a mark
* @param {*} [options.tooltip] - tooltip text to show upon mouse hover
* @param {Array<Transform>} [options.transforms=[]] - list of post-encoding transforms to apply after any "encode" blocks and which operate directly on mark scenegraph items
* @param {Array<Trigger>} [options.triggers=[]] - list of triggers for modifying mark properties in response to signal changes
* @param {number} [options.width] - width of the mark in pixels
* @param {number} [options.x] - primary x-coordinate in pixels
* @param {number} [options.x2] - secondary x-coordinate in pixels
* @param {number} [options.xc] - center x-coordinate
* @param {number} [options.y] - primary y-coordinate in pixels
* @param {number} [options.y2] - secondary y-coordinate in pixels
* @param {number} [options.yc] - center y-coordinate
* @param {number} [options.zindex=0] - integer z-index indicating the layering of a mark relative to other marks
* @throws {TypeError} options argument must be an object
* @throws {Error} must provide valid options
* @returns {Mark} mark instance
*
* @example
* var mark = new Mark({
*     'type': 'line'
* });
* // returns <Mark>
*/
function Mark( options ) {
	var self;
	var opts;
	var keys;
	var v;
	var k;
	var i;
	if ( !( this instanceof Mark ) ) {
		if ( arguments.length ) {
			return new Mark( options );
		}
		return new Mark();
	}
	if ( !isObject( options ) ) {
		throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
	}
	self = this;
	EventEmitter.call( this );

	// Resolve the default configuration:
	opts = defaults();

	// Set internal properties according to the default configuration...
	keys = objectKeys( opts );
	for ( i = 0; i < keys.length; i++ ) {
		k = keys[ i ];
		this[ '_'+k ] = opts[ k ];
		if ( k === 'on' ) {
			this._triggers = opts[ k ]; // set an alias
		} else if ( k === 'triggers' ) {
			this._on = opts[ k ]; // set an alias
		}
	}
	// Check for required properties...
	if ( !hasProp( options, 'type' ) ) {
		throw new TypeError( 'invalid argument. Options argument must specify the mark type.' );
	}
	// Define an internal change event listener:
	this._onChange = onChange;

	// Add change listeners to default event emitters:
	if ( this._clip && typeof this._clip.on === 'function' ) {
		this._addChangeListener( this._clip );
	}
	this._addChangeListener( this._sort );

	// Validate provided options by attempting to assign option values to corresponding fields...
	for ( i = 0; i < properties.length; i++ ) {
		k = properties[ i ];
		if ( !hasProp( options, k ) ) {
			continue;
		}
		v = options[ k ];
		if ( k === 'on' ) {
			// Avoid conflict with event emitter method:
			k = 'triggers';
		}
		try {
			this[ k ] = v;
		} catch ( err ) {
			debug( 'Encountered an error. Error: %s', err.message );

			// FIXME: retain thrown error type
			throw new Error( transformErrorMessage( err.message ) );
		}
	}
	return this;

	/**
	* Callback invoked upon a change event.
	*
	* @private
	* @param {Object} event - event object
	*/
	function onChange( event ) {
		debug( 'Received a change event: %s', JSON.stringify( event ) );
		self.emit( 'change', event );
	}
}

/*
* Inherit from the `EventEmitter` prototype.
*/
inherit( Mark, EventEmitter );

/**
* Constructor name.
*
* @private
* @name name
* @memberof Mark
* @readonly
* @type {string}
*/
setNonEnumerableReadOnly( Mark, 'name', 'Mark' );

/**
* Adds an internal listener to a change event on a child instance.
*
* @private
* @name _addChangeListener
* @memberof Mark.prototype
* @type {Function}
* @param {Object} emitter - event emitter
* @returns {Mark} visualization instance
*/
setNonEnumerableReadOnly( Mark.prototype, '_addChangeListener', function addChangeListener( emitter ) {
	if ( emitter && typeof emitter.on === 'function' ) {
		emitter.on( 'change', this._onChange );
	}
	return this;
});

/**
* Adds internal listeners to change events on child instances.
*
* @private
* @name _addChangeListeners
* @memberof Mark.prototype
* @type {Function}
* @param {ArrayLikeObject<Object>} emitters - list of event emitters
* @returns {Mark} visualization instance
*/
setNonEnumerableReadOnly( Mark.prototype, '_addChangeListeners', function addChangeListeners( emitters ) {
	var i;
	for ( i = 0; i < emitters.length; i++ ) {
		this._addChangeListener( emitters[ i ] );
	}
	return this;
});

/**
* Removes an internal listener to a change event on a child instance.
*
* @private
* @name _removeChangeListener
* @memberof Mark.prototype
* @type {Function}
* @param {Object} emitter - event emitter
* @returns {Mark} visualization instance
*/
setNonEnumerableReadOnly( Mark.prototype, '_removeChangeListener', function removeChangeListener( emitter ) {
	if ( emitter && typeof emitter.removeListener === 'function' ) {
		emitter.removeListener( 'change', this._onChange );
	}
	return this;
});

/**
* Removes internal listeners to change events on child instances.
*
* @private
* @name _removeChangeListeners
* @memberof Mark.prototype
* @type {Function}
* @param {ArrayLikeObject<Object>} emitters - list of event emitters
* @returns {Mark} visualization instance
*/
setNonEnumerableReadOnly( Mark.prototype, '_removeChangeListeners', function removeChangeListeners( emitters ) {
	var i;
	for ( i = 0; i < emitters.length; i++ ) {
		this._removeChangeListener( emitters[ i ] );
	}
	return this;
});

